const defaults={id:'preferences',version:5,skinId:'builtin',skinLayout:true,skinKeys:true,skipEnabled:true,autoSkipIntro:false,receptorStroke:3,offset:0,ruleset:'lazer',odMode:'map',od:5,receptorStyle:'hollow',noteHeight:14,keyHeight:64,glow:.5,secondaryColor:'#83c8ee',centerColor:'#efc285',judgmentY:40,cacheMaps:true,cacheLimit:512,windows:[22,45,90,135,180],volume:.6,hitVolume:.3,preservePitch:false,metronome:false,noFail:true,scroll:650,laneWidth:65,shape:'bar',color:'#b5f56a',dim:.85,receptor:82,upscroll:false,sv:false,beatLines:true,showKeys:true,showError:true,leadIn:1.5,target:96,rateStep:.05,autoRate:false,bindings:structuredClone(DEFAULT_KEYS)};
let settings=structuredClone(defaults),charts=[],scores=[],selected=null,collection='all',collections=[],collectionNames=[],chartPrefs={},urls=new Map(),busy=false,bindTarget=null,currentRecord=null,lastView='library',toastTimer,playing=null,runToken=0,cal=null;
let config={rate:1,mirror:false,random:false,noLN:false,a:0,b:0,loop:true,offset:0};const clock=new AudioClock(),renderer=new Renderer($('game'));
const uid=()=>crypto.randomUUID();
function toast(message,ms=3500){$('toast').textContent=message;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',ms)}
function notice(title,body){$('noticeTitle').textContent=title;$('noticeBody').textContent=body;if(!$('notice').open)$('notice').showModal()}
function timingProfile(chart,rate){if(settings.ruleset==='lazer'){let all=lazerWindows(settings.odMode==='override'?settings.od:chart?.od??5,rate);return{windows:all.slice(0,5),missWindow:all[5],ruleset:'lazer'}}return{windows:settings.ruleset==='custom'?[...settings.windows]:[...(RULESETS[settings.ruleset]||RULESETS.training)],ruleset:settings.ruleset}}
