function keysFor(n){return settings.bindings[n]||DEFAULT_KEYS[n]}
function rememberSettings(){return store.put('settings',settings).catch(e=>toast('Could not save preferences: '+e.message))}
function rememberConfig(){if(!selected)return;chartPrefs[selected.id]={...config};store.put('settings',{id:'chart-prefs',value:chartPrefs}).catch(e=>toast(e.message))}
function go(page){if(playing)return;runToken++;if(page!=='online')online.stopPreview();lastView=page;document.querySelectorAll('.page').forEach(p=>p.classList.toggle('active',p.id===page));document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.page===page));if(page==='history')renderHistory();if(page==='settings')renderSettings();if(page==='online')online.ensureLoaded()}
function statsHTML(items){return items.map(([l,v])=>`<div class="stat-tile"><span>${esc(l)}</span><b>${esc(v)}</b></div>`).join('')}
async function assetURL(id){if(!id)return null;if(id.startsWith('/api/assets/')){if(urls.has(id))return urls.get(id);try{let blob=await getHostedAsset(id,{cache:settings.cacheMaps,limitMB:settings.cacheLimit}),u=URL.createObjectURL(blob);urls.set(id,u);return u}catch{return null}}if(urls.has(id))return urls.get(id);let asset=await store.get('assets',id);if(!asset)return null;let u=URL.createObjectURL(asset.blob);urls.set(id,u);return u}
function addCollectionBar(){let bar=document.querySelector('.collection-filter');if(!bar){bar=document.createElement('div');bar.className='collection-filter';document.querySelector('.toolbar').before(bar)}let names=['all','favorites',...collectionNames];bar.innerHTML=names.map(n=>`<button data-collection="${esc(n)}" class="${collection===n?'on':''}">${n==='all'?'All charts':n==='favorites'?'★ Favorites':esc(n)}</button>`).join('');bar.querySelectorAll('button').forEach(b=>b.onclick=()=>{collection=b.dataset.collection;renderLibrary()})}
function renderLibrary(){addCollectionBar();let q=$('search').value.toLowerCase().trim(),key=$('keyFilter').value,list=charts.filter(c=>(key==='all'||c.keys===+key)&&(!q||`${c.title} ${c.artist} ${c.creator} ${c.version} ${c.tags}`.toLowerCase().includes(q))&&(collection==='all'||collection==='favorites'&&c.favorite||(c.collections||[]).includes(collection)));let sort=$('sort').value;list.sort((a,b)=>sort==='title'?a.title.localeCompare(b.title):sort==='density'?b.analysis.peak-a.analysis.peak:sort==='bpm'?b.bpm-a.bpm:sort==='length'?b.duration-a.duration:(b.added||0)-(a.added||0));$('chartCount').textContent=`${list.length} CHART${list.length===1?'':'S'} / ${charts.length} TOTAL`;
 $('charts').innerHTML=list.length?list.map(c=>`<button class="chart-row ${c.id===selected?.id?'selected':''}" data-id="${esc(c.id)}"><div class="chart-icon" data-bg="${esc(c.backgroundId||'')}">${c.keys}K</div><div class="chart-copy"><b>${c.hosted?'<span class="server-chart">SERVER</span>':''}${c.favorite?'<span class="fav-star">★ </span>':''}${esc(c.title)}</b><small>${esc(c.artist)} · ${esc(c.creator)}</small><em>${esc(c.version)}</em></div><div class="row-stats"><span>${c.keys}K<small>KEYS</small></span><span>${c.analysis.peak.toFixed(1)}<small>PEAK NPS</small></span><span>${fmt(c.duration)}<small>LENGTH</small></span></div></button>`).join(''):'<div class="empty">No matching charts.<br>Import an .osz file or generate a drill in Pattern lab.</div>';
 document.querySelectorAll('.chart-row').forEach(b=>{b.onclick=()=>selectChart(b.dataset.id);b.ondblclick=()=>launch('play')});document.querySelectorAll('[data-bg]').forEach(async e=>{let u=await assetURL(e.dataset.bg);if(u&&e.isConnected)e.innerHTML=`<img src="${u}" alt="">`});}
function selectChart(id){selected=charts.find(c=>c.id===id);if(!selected)return;config={rate:1,mirror:false,random:false,noLN:false,a:0,b:selected.duration,loop:true,offset:0,...chartPrefs[id]};config.a=clamp(config.a,0,selected.duration-.2);config.b=clamp(config.b,config.a+.2,selected.duration);renderLibrary();renderDetail()}
function renderDetail(){let c=selected;if(!c){$('detail').innerHTML='<h2>Your library is ready.</h2><p>Import an osu!mania map pack to begin, or use Pattern lab to create a focused drill.</p><button class="accent" id="emptyImport">Import maps</button>';$('emptyImport').onclick=()=>$('files').click();return}let a=c.analysis,best=scores.filter(s=>s.chartId===c.id&&!s.practice&&!s.aborted&&s.rate===config.rate&&s.ruleset===settings.ruleset&&s.mirror===config.mirror&&s.random===config.random&&s.noLN===config.noLN).sort((a,b)=>b.accuracy-a.accuracy)[0];
 $('detail').innerHTML=`<div class="detail-art" id="detailArt"><span class="art-tag">${esc(c.source)} / ${c.keys}K</span></div><h2>${esc(c.title)}</h2><div class="artist">${esc(c.artist)} · mapped by ${esc(c.creator)}</div><div class="version">${esc(c.version)}</div><div class="detail-stats"><div><b>${Math.round(c.bpm)}</b><small>BPM</small></div><div><b>${a.notes}</b><small>NOTES</small></div><div><b>${a.peak.toFixed(1)}</b><small>PEAK NPS</small></div><div><b>${fmt(c.duration)}</b><small>LENGTH</small></div></div><div class="section-title"><span class="eyebrow">DENSITY & PRACTICE RANGE</span><span class="muted">${esc(a.pattern)} · ${Math.round(a.ln/a.notes*100)}% LN</span></div><canvas id="density" class="density" aria-label="Chart density. Click to set practice start; Shift click to set end."></canvas><div class="graph-caption"><span>CLICK → A · SHIFT CLICK → B</span><span>${a.average.toFixed(1)} AVG NPS</span></div><div class="form-grid"><label>A — start (seconds)<input id="rangeA" type="number" min="0" max="${c.duration}" step="0.1" value="${config.a.toFixed(1)}"></label><label>B — end (seconds)<input id="rangeB" type="number" min="0" max="${c.duration}" step="0.1" value="${config.b.toFixed(1)}"></label></div>${c.bookmarks?.length?'<div class="mods">'+c.bookmarks.map((t,i)=>'<button class="mod" data-bookmark="'+i+'">↦ '+fmt(t)+'</button>').join('')+'</div>':''}<label>Playback rate<div class="rate-control"><button id="rateDown">−</button><input id="rate" type="number" min="0.25" max="2.5" step="0.05" value="${config.rate.toFixed(2)}" aria-label="Playback rate"><button id="rateUp">＋</button></div></label><div class="mods">${['mirror','random','noLN'].map(n=>`<button class="mod ${config[n]?'on':''}" data-mod="${n}">${n==='noLN'?'No holds':n[0].toUpperCase()+n.slice(1)}</button>`).join('')}<button class="mod ${config.loop?'on':''}" id="loopConfig">↻ A/B loop</button></div><label>Chart offset (ms) <input id="chartOffset" type="number" min="-500" max="500" value="${config.offset}"></label>${!c.audioId&&!c.generated?'<div class="notice-inline">Audio missing. Attach the map audio below. Silent practice is available.</div>':''}${c.warnings?.length?`<div class="notice-inline">${esc(c.warnings.join(' · '))}</div>`:''}<div class="detail-actions"><button class="accent play" id="playChart">▶ Play full chart</button><button id="practiceChart">◎ Practice A/B</button><button id="autoChart">▷ Autoplay</button></div><div class="mini-actions"><button id="favorite">${c.favorite?'★ Favorited':'☆ Favorite'}</button><button id="addCollection">＋ Collection</button>${c.hosted?'<button id="cacheSelected">↓ Cache for offline play</button>':''}<button id="attachAudio">Attach audio</button><button id="exportChart">Export chart</button><button id="deleteChart">Delete</button></div><div class="muted">${best?`Best at this rate/mods: <b>${best.accuracy.toFixed(2)}%</b> · ${best.score.toLocaleString()} points`:'No completed score at this rate/mod combination yet.'}<br>Bindings: ${keysFor(c.keys).map(keyName).join(' · ')}</div>`;
 assetURL(c.backgroundId).then(u=>{if(u&&$('detailArt'))$('detailArt').insertAdjacentHTML('afterbegin',`<img src="${u}" alt="">`)});drawDensity();
 $('rangeA').oninput=e=>{config.a=clamp(+e.target.value||0,0,config.b-.2);rememberConfig();drawDensity()};$('rangeB').oninput=e=>{config.b=clamp(+e.target.value||c.duration,config.a+.2,c.duration);rememberConfig();drawDensity()};$('rate').oninput=e=>{config.rate=Math.round(clamp(+e.target.value||1,.25,2.5)*100)/100;rememberConfig()};$('rateDown').onclick=()=>setRate(config.rate-.05);$('rateUp').onclick=()=>setRate(config.rate+.05);document.querySelectorAll('[data-mod]').forEach(b=>b.onclick=()=>{config[b.dataset.mod]=!config[b.dataset.mod];rememberConfig();renderDetail()});$('loopConfig').onclick=()=>{config.loop=!config.loop;rememberConfig();renderDetail()};$('chartOffset').oninput=e=>{config.offset=clamp(+e.target.value||0,-500,500);rememberConfig()};document.querySelectorAll('[data-bookmark]').forEach(b=>b.onclick=()=>{let i=+b.dataset.bookmark;config.a=clamp(c.bookmarks[i],0,c.duration-.2);config.b=clamp(c.bookmarks[i+1]||c.duration,config.a+.2,c.duration);rememberConfig();renderDetail()});$('playChart').onclick=()=>launch('play');$('practiceChart').onclick=()=>launch('practice');$('autoChart').onclick=()=>launch('auto');$('favorite').onclick=async()=>{c.favorite=!c.favorite;await store.put('charts',c);renderLibrary();renderDetail()};$('addCollection').onclick=()=>collectionDialog(c);if($('cacheSelected'))$('cacheSelected').onclick=async()=>{try{await cacheCharts([c],{cache:true,limitMB:settings.cacheLimit,progress:(i,n)=>toast('Caching '+i+'/'+n+' files…')});toast('Audio and background cached for offline play.')}catch(e){toast(e.message,6000)}};$('attachAudio').onclick=()=>attachAudio(c);$('exportChart').onclick=()=>download(c.raw||JSON.stringify(c,null,2),c.title+(c.raw?'.osu':'.pulse-chart.json'),'text/plain');$('deleteChart').onclick=()=>deleteDialog(c);}
function setRate(rate){config.rate=Math.round(clamp(+rate||1,.25,2.5)*100)/100;rememberConfig();renderDetail()}
function graphContext(id){let cv=$(id),r=cv.getBoundingClientRect(),dpr=devicePixelRatio||1;cv.width=Math.max(1,Math.round(r.width*dpr));cv.height=Math.max(1,Math.round(r.height*dpr));let ctx=cv.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);return {ctx,w:r.width,h:r.height,cv}}
function drawDensity(){if(!$('density')||!selected)return;let {ctx:c,w,h,cv}=graphContext('density'),bins=selected.analysis.bins,max=selected.analysis.peak||1;c.fillStyle='#11161f';c.fillRect(0,0,w,h);let dx=w/bins.length;bins.forEach((v,i)=>{c.fillStyle=2*i>=config.a&&2*i<=config.b?settings.color:'#526078';c.fillRect(i*dx,h-v/max*(h-8),Math.max(1,dx-1),v/max*(h-8))});c.fillStyle='#fff';for(let t of[config.a,config.b])c.fillRect(t/selected.duration*w,0,1,h);cv.onclick=e=>{let t=(e.clientX-cv.getBoundingClientRect().left)/w*selected.duration;if(e.shiftKey)config.b=clamp(t,config.a+.2,selected.duration);else config.a=clamp(t,0,config.b-.2);rememberConfig();renderDetail()}}
function collectionDialog(c){$('noticeTitle').textContent='Chart collections';$('noticeBody').innerHTML='<label>Collection name<input id="newCollection" maxlength="40" placeholder="e.g. Stamina, LN practice"></label><button id="saveCollection" class="accent">Add chart</button><div id="existingCollections"></div>';$('notice').showModal();$('saveCollection').onclick=async()=>{let name=$('newCollection').value.trim();if(!name||['all','favorites'].includes(name.toLowerCase()))return toast('Choose a collection name.');c.collections=[...new Set([...(c.collections||[]),name])];if(!collectionNames.includes(name))collectionNames.push(name);await Promise.all([store.put('charts',c),store.put('settings',{id:'collections',value:collectionNames})]);$('notice').close();renderLibrary();toast('Added to '+name)};if(c.collections?.length){$('existingCollections').textContent='Current: '+c.collections.join(', ');let b=document.createElement('button');b.textContent='Remove from all collections';b.onclick=async()=>{c.collections=[];await store.put('charts',c);$('notice').close();renderLibrary()};$('existingCollections').append(b)}}
function deleteDialog(c){$('noticeTitle').textContent=c.hosted?'Hide server chart on this device?':'Delete this chart?';$('noticeBody').innerHTML=`<p>${esc(c.title)} [${esc(c.version)}] will be removed. Other difficulties and score history remain. ${c.hosted?'The server copy stays available in Online maps.':''}</p><button id="confirmDelete">Delete chart</button>`;$('notice').showModal();$('confirmDelete').onclick=async()=>{if(c.hosted){let hidden=(await store.get('settings','hosted-hidden'))?.value||[];await store.put('settings',{id:'hosted-hidden',value:[...new Set([...hidden,c.id])]})}await store.remove('charts',c.id);charts=charts.filter(x=>x.id!==c.id);selected=null;$('notice').close();if(charts.length)selectChart(charts[0].id);else{renderLibrary();renderDetail()}toast('Chart deleted')}}
function download(data,name,type='application/json'){let u=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=u;a.download=name.replace(/[<>:"/\\|?*]/g,'_');a.click();setTimeout(()=>URL.revokeObjectURL(u),30000)}
async function attachAudio(c){let input=document.createElement('input');input.type='file';input.accept='audio/*';input.onchange=async()=>{let file=input.files[0];if(!file)return;let id=await store.fingerprint(await file.arrayBuffer());await store.put('assets',{id,blob:file});c.audioId=id;c.audioName=file.name;await store.put('charts',c);renderDetail();toast('Audio attached')};input.click()}
const pathKey=p=>p.replaceAll('\\','/').replace(/^\.\//,'').toLowerCase();
function unpack(buffer){return new Promise((resolve,reject)=>{let worker=new Worker(new URL('import-worker.mjs',document.baseURI),{type:'module'});worker.onmessage=e=>{worker.terminate();e.data.error?reject(Error(e.data.error)):resolve(e.data.files)};worker.onerror=e=>{worker.terminate();reject(Error(e.message))};worker.postMessage(buffer,[buffer])})}
async function importFiles(files){if(busy)return toast('An import is already in progress.');if(playing)return toast('Return to the library before importing.');busy=true;$('importTop').disabled=true;let report=[],added=0;try{let loose=[];for(let file of files){if(file.size>220*1024*1024){report.push(`${file.name}: exceeds 220 MB file limit`);continue}if(/\.osk$/i.test(file.name)){let skin=await importSkin(file);settings.skinId=skin.id;await rememberSettings();report.push('Skin imported: '+skin.name);continue}if(/\.(osz|zip)$/i.test(file.name)){toast('Unpacking '+file.name+'…',20000);try{let entries=await unpack(await file.arrayBuffer());let backup=entries.find(e=>pathKey(e.path)==='pulse-backup.json');if(backup){await restoreBackup(entries,backup);report.push(file.name+': restored backup');continue}let result=await importEntries(entries,file.name);added+=result.added;report.push(...result.report)}catch(e){report.push(file.name+': '+e.message)}}else if(/\.json$/i.test(file.name)){try{let data=JSON.parse(await file.text());if(data.type==='pulse-replay'){await importReplay(data);report.push(file.name+': replay loaded')}else if(data.type==='pulse-settings'){await applyImportedSettings(data.settings);report.push('Settings imported')}else if(data.notes&&data.generated){let c=validateChart(data);c.analysis=analyze(c);c.added=Date.now();await store.put('charts',c);added++}else report.push(file.name+': unrecognized JSON file')}catch(e){report.push(file.name+': '+e.message)}}else loose.push({path:file.webkitRelativePath||file.name,bytes:new Uint8Array(await file.arrayBuffer())})}if(loose.length){let result=await importEntries(loose,'Selected files');added+=result.added;report.push(...result.report)}charts=await store.all('charts');scores=await store.all('scores');collectionNames=(await store.get('settings','collections'))?.value||[];renderLibrary();if(added&&charts.length)selectChart(charts.sort((a,b)=>b.added-a.added)[0].id);else renderDetail();notice('Import complete',`${added} chart(s) added or updated.\n\n${report.join('\n')||'No .osu files found. Select native mania .osu charts with their audio, or an .osz archive.'}`)}catch(e){notice('Import failed',e.message)}finally{clearTimeout(toastTimer);$('toast').style.display='none';busy=false;$('importTop').disabled=false;$('files').value='';$('folder').value=''}}
async function importEntries(entries,label){let lookup=new Map(entries.map(e=>[pathKey(e.path),e])),report=[],added=0,assetIds=new Map();const findAsset=(name,dir)=>lookup.get(pathKey(dir+name))||lookup.get(pathKey(name))||entries.find(e=>pathKey(e.path).endsWith('/'+pathKey(name)));async function saveAsset(entry){if(!entry)return null;if(assetIds.has(entry.path))return assetIds.get(entry.path);let id=await store.fingerprint(entry.bytes);let mime=/\.(jpg|jpeg)$/i.test(entry.path)?'image/jpeg':/\.png$/i.test(entry.path)?'image/png':/\.webp$/i.test(entry.path)?'image/webp':/\.mp3$/i.test(entry.path)?'audio/mpeg':/\.ogg$/i.test(entry.path)?'audio/ogg':/\.wav$/i.test(entry.path)?'audio/wav':/\.flac$/i.test(entry.path)?'audio/flac':'application/octet-stream';await store.put('assets',{id,blob:new Blob([entry.bytes],{type:mime})});assetIds.set(entry.path,id);return id}
 for(let entry of entries.filter(e=>/\.osu$/i.test(e.path))){try{let text=strFromU8(entry.bytes),c=parseOsu(text,entry.path);c.id=await store.fingerprint(entry.bytes);let old=await store.get('charts',c.id),dir=entry.path.slice(0,entry.path.replaceAll('\\','/').lastIndexOf('/')+1);c.audioId=await saveAsset(findAsset(c.audioName,dir))||old?.audioId||null;c.backgroundId=await saveAsset(findAsset(c.backgroundName,dir))||old?.backgroundId||null;c.added=Date.now();c.favorite=old?.favorite||false;c.collections=old?.collections||[];c.analysis=analyze(c);await store.put('charts',c);added++;report.push(`${c.title} [${c.version}] — ${c.keys}K, ${c.notes.length} notes${!c.audioId?' (audio missing)':''}`)}catch(e){report.push(e.message)}}if(!added&&!report.length)report.push(label+': no .osu files found');return{added,report}}
function validateChart(c){if(typeof c.id!=='string'||!c.id||typeof c.title!=='string'||!Number.isInteger(c.keys)||c.keys<1||c.keys>10||!Number.isFinite(c.duration)||c.duration<=0||!Array.isArray(c.notes)||!c.notes.length||c.notes.length>500000||!c.notes.every(n=>Number.isFinite(n.t)&&Number.isFinite(n.end)&&n.t>=0&&n.end>=n.t&&Number.isInteger(n.lane)&&n.lane>=0&&n.lane<c.keys))throw Error('Invalid chart data');c.notes.sort((a,b)=>a.t-b.t||a.lane-b.lane);c.timing=Array.isArray(c.timing)?c.timing.filter(p=>Number.isFinite(p.t)&&Number.isFinite(p.beat)):[];return c}
async function backupLibrary(){toast('Preparing library backup…',20000);try{let savedCharts=await store.all('charts'),savedScores=await store.all('scores'),prefs=await store.all('settings'),assets=await store.all('assets'),archive={};for(let a of assets)archive['assets/'+a.id]=new Uint8Array(await a.blob.arrayBuffer());archive['pulse-backup.json']=strToU8(JSON.stringify({type:'pulse-backup',version:1,charts:savedCharts,scores:savedScores,settings:prefs,assets:assets.map(a=>({id:a.id,type:a.blob.type}))}));download(zipSync(archive,{level:0}),'pulse-library-backup.zip','application/zip');toast('Backup downloaded')}catch(e){notice('Backup failed',e.message)}}
async function restoreBackup(entries,manifest){let data=JSON.parse(strFromU8(manifest.bytes));if(data.type!=='pulse-backup'||data.version!==1||!Array.isArray(data.charts))throw Error('Unsupported backup');let valid=data.charts.map(validateChart);for(let c of valid)c.analysis=analyze(c);let lookup=new Map(entries.map(e=>[e.path,e.bytes]));for(let a of data.assets||[]){let bytes=lookup.get('assets/'+a.id);if(bytes)await store.put('assets',{id:a.id,blob:new Blob([bytes],{type:a.type})})}for(let c of valid)await store.put('charts',c);for(let s of data.scores||[])if(validRecord(s))await store.put('scores',s);for(let p of data.settings||[]){if(p.id==='preferences')await applyImportedSettings(p);else if(['collections','chart-prefs'].includes(p.id))await store.put('settings',p)}chartPrefs=(await store.get('settings','chart-prefs'))?.value||{};toast('Backup restored')}
function validRecord(s){return s&&typeof s.id==='string'&&typeof s.chartId==='string'&&Number.isFinite(s.rate)&&s.rate>=.25&&s.rate<=2.5&&Number.isFinite(s.accuracy)&&Array.isArray(s.hits)&&Array.isArray(s.events)&&s.events.every(e=>Number.isFinite(e.t)&&Number.isInteger(e.lane)&&e.lane>=0&&e.lane<10&&typeof e.down==='boolean')&&validateWindows(s.windows||[])}
async function importReplay(data){if(!validRecord(data.record))throw Error('Invalid replay');let c=charts.find(c=>c.id===data.record.chartId)||await store.get('charts',data.record.chartId);if(!c)throw Error('Import the matching chart before this replay.');await store.put('scores',{...data.record,id:uid(),imported:true});toast('Replay added to History')}
function renderSettings(){document.querySelectorAll('[data-setting]').forEach(e=>{let v=settings[e.dataset.setting];if(e.type==='checkbox')e.checked=v;else e.value=v;e.onchange=()=>{let key=e.dataset.setting,value=e.type==='checkbox'?e.checked:e.type==='number'||e.type==='range'?+e.value:e.value;const bounds={offset:[-500,500],scroll:[100,1800],laneWidth:[30,100],volume:[0,1],hitVolume:[0,1],dim:[0,1],receptor:[60,90],leadIn:[.5,5],target:[50,100],rateStep:[.01,.2],od:[0,10],noteHeight:[6,30],keyHeight:[24,110],glow:[0,1],judgmentY:[20,65],cacheLimit:[64,2048],receptorStroke:[1,8]};if(bounds[key])value=clamp(Number.isFinite(value)?value:defaults[key],...bounds[key]);settings[key]=value;rememberSettings();if(e.type==='range'){settingsUI.update()}else renderSettings()};if(e.type==='range')e.oninput=e.onchange});$('customWindows').innerHTML=settings.ruleset==='custom'?settings.windows.map((v,i)=>`<label>${LABELS[i]} ±ms<input type="number" data-window="${i}" min="5" max="300" value="${v}"></label>`).join(''):'';document.querySelectorAll('[data-window]').forEach(e=>e.onchange=()=>{let values=[...settings.windows];values[+e.dataset.window]=+e.value;if(!validateWindows(values)){toast('Windows must increase strictly and stay between 5 and 300 ms.');renderSettings();return}settings.windows=values;rememberSettings()});renderBindings();storageInfo();settingsUI.update();skinUI.refresh().catch(()=>{})}
function renderBindings(){let n=+$('bindMode').value;$('bindings').innerHTML=keysFor(n).map((key,i)=>`<button data-bind="${i}" title="Rebind lane ${i+1}">${keyName(key)}<small style="display:block;color:#8f9caf;font-size:8px">LANE ${i+1}</small></button>`).join('');document.querySelectorAll('[data-bind]').forEach(b=>b.onclick=()=>{bindTarget={mode:n,lane:+b.dataset.bind};renderBindings();document.querySelector(`[data-bind="${bindTarget.lane}"]`).classList.add('listening');document.querySelector(`[data-bind="${bindTarget.lane}"]`).textContent='Press key…'})}
async function applyImportedSettings(incoming){let clean=structuredClone(defaults);for(let key of Object.keys(defaults)){if(key==='bindings'||key==='id'||key==='windows')continue;let v=incoming[key];if(typeof v===typeof defaults[key])clean[key]=v}if(!RULESETS[clean.ruleset]&&!['custom','lazer'].includes(clean.ruleset))clean.ruleset='training';if(validateWindows(incoming.windows||[]))clean.windows=incoming.windows;if(incoming.bindings){for(let n=1;n<=10;n++){let b=incoming.bindings[n];if(Array.isArray(b)&&b.length===n&&b.every(k=>typeof k==='string'&&/^(Key[A-Z]|Digit[0-9]|Space|Semicolon|Quote|Comma|Period|Slash|Backslash|BracketLeft|BracketRight|Minus|Equal)$/.test(k)&&!reserved.has(k))&&new Set(b).size===n)clean.bindings[n]=b}}clean.offset=clamp(clean.offset,-500,500);clean.scroll=clamp(clean.scroll,100,1800);clean.laneWidth=clamp(clean.laneWidth,30,100);clean.volume=clamp(clean.volume,0,1);clean.hitVolume=clamp(clean.hitVolume,0,1);clean.dim=clamp(clean.dim,0,1);clean.receptor=clamp(clean.receptor,60,90);clean.leadIn=clamp(clean.leadIn,.5,5);clean.target=clamp(clean.target,50,100);clean.rateStep=clamp(clean.rateStep,.01,.2);if(!/^#[a-f0-9]{6}$/i.test(clean.color))clean.color=defaults.color;if(!['bar','circle','diamond'].includes(clean.shape))clean.shape='bar';for(let [key,bounds] of Object.entries({od:[0,10],noteHeight:[6,30],keyHeight:[24,110],glow:[0,1],judgmentY:[20,65],cacheLimit:[64,2048]}))clean[key]=clamp(Number.isFinite(clean[key])?clean[key]:defaults[key],...bounds);for(let key of ['secondaryColor','centerColor'])if(!/^#[a-f0-9]{6}$/i.test(clean[key]))clean[key]=defaults[key];if(!['map','override'].includes(clean.odMode))clean.odMode='map';if(!['piano','minimal','circles','hollow'].includes(clean.receptorStyle))clean.receptorStyle='hollow';settings=clean;await rememberSettings();renderSettings();renderDetail()}
async function storageInfo(){if(!navigator.storage)return;let e=await navigator.storage.estimate(),persistent=await navigator.storage.persisted();$('storageInfo').textContent=`${((e.usage||0)/1048576).toFixed(1)} MB used · ${persistent?'Persistent storage enabled':'Storage may be cleared by the browser when space is low'}`}
function renderHistory(){let sorted=[...scores].sort((a,b)=>b.date-a.date);$('historyStats').innerHTML=statsHTML([['SAVED ATTEMPTS',scores.length],['FULL COMPLETIONS',scores.filter(s=>!s.practice&&!s.aborted).length],['NOTES JUDGED',scores.reduce((a,s)=>a+s.hits.length,0).toLocaleString()],['BEST ACCURACY',scores.some(s=>!s.aborted&&s.hits.length)?Math.max(...scores.filter(s=>!s.aborted&&s.hits.length).map(s=>s.accuracy)).toFixed(2)+'%':'—']]);$('historyList').innerHTML=sorted.length?sorted.map(s=>`<div class="history-row"><div><b>${esc(s.title)}</b><small>${esc(s.version)} · ${s.keys}K · ${s.rate.toFixed(2)}× · ${s.ruleset||'training'} ${s.mirror?'MIRROR ':''}${s.random?'RANDOM ':''}${s.noLN?'NO HOLDS ':''} ${s.practice?`PRACTICE ${fmt(s.start)}–${fmt(s.end)}${s.aborted?' · PARTIAL':''}`:s.aborted?'PARTIAL RUN':'FULL RUN'}</small></div><div>${s.accuracy.toFixed(2)}%<small>ACCURACY</small></div><div>${s.maxCombo}×<small>COMBO</small></div><div class="history-date">${new Date(s.date).toLocaleDateString()}<small>${new Date(s.date).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}</small></div><button data-result="${esc(s.id)}">View results</button></div>`).join(''):'<div class="empty">No attempts yet. Your plays and practice loops will appear here.</div>';document.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>viewResults(scores.find(s=>s.id===b.dataset.result)))}
async function launch(mode='play',extra={}){online.stopPreview();for(let d of document.querySelectorAll('dialog[open]'))d.close();toast('Preparing chart…');let chart=extra.chart||selected;if(!chart)return;let token=++runToken;if(playing){clock.stop();playing=null}document.activeElement?.blur();try{await clock.init();let blob=null;if(chart.audioId){if(chart.audioId.startsWith('/api/assets/')){blob=await getHostedAsset(chart.audioId,{cache:settings.cacheMaps,limitMB:settings.cacheLimit})}else blob=(await store.get('assets',chart.audioId))?.blob;}await clock.load(blob,chart);let skin=await loadSkin(settings.skinId,chart.keys);clock.skinHit=skin?await skin.getAudio(clock.ctx):null;if(token!==runToken)return;let practice=mode==='practice',replay=extra.replay,seed=replay?.seed||Math.floor(Math.random()*1e9);let opts=replay?{rate:replay.rate,offset:replay.offset,windows:replay.windows,missWindow:replay.missWindow,ruleset:replay.ruleset,start:replay.start,end:replay.end,mirror:replay.mirror,random:replay.random,noLN:replay.noLN,seed:replay.seed}:{rate:config.rate,offset:settings.offset+(chartPrefs[chart.id]?.offset||config.offset||0),...timingProfile(chart,config.rate),start:practice?config.a:0,end:practice?config.b:chart.duration,mirror:config.mirror,random:config.random,noLN:config.noLN,seed};practice=replay?replay.practice:practice;let session=new Session(chart,opts);if(!session.total){toast('No complete notes in this A/B range. Widen the range.');return}playing={chart,session,mode:replay?'replay':mode,practice,paused:false,replay,replayCursor:0,started:Date.now(),token,loop:practice&&config.loop&&!replay,opts,settings:{...structuredClone(settings),ruleset:replay?.ruleset||settings.ruleset},keys:[...keysFor(chart.keys)],lastUI:0,lastHitCount:0,pointerLanes:new Map(),skips:[],replaySkipCursor:0};renderer.set(chart,session,playing.settings,playing.keys);renderer.setSkin(skin);renderer.background=null;$('lastHit').textContent='';assetURL(chart.backgroundId).then(imageURL=>{if(!imageURL||playing?.token!==token)return;let im=new Image();im.src=imageURL;im.onload=()=>{if(playing?.token===token)renderer.background=im}}).catch(e=>console.warn('Background:',e.message));$('playScreen').hidden=false;$('app').hidden=true;document.querySelector('header').hidden=true;$('pauseOverlay').hidden=true;$('playTitle').textContent=chart.title;$('playMeta').textContent=`${chart.artist} · ${chart.version} · ${chart.keys}K`;$('playMode').textContent=replay?'REPLAY':mode==='auto'?'AUTOPLAY':practice?'PRACTICE':'FULL RUN';$('field').style.width=skin&&settings.skinLayout?(skin.config.widths.reduce((a,n)=>a+n,0)+skin.config.spacing.slice(0,-1).reduce((a,n)=>a+n,0))*$('field').parentElement.clientHeight/480+'px':chart.keys*settings.laneWidth+'px';$('seek').max=chart.duration;$('seek').disabled=!practice;$('timeEnd').textContent=fmt(chart.duration);$('liveJudgments').innerHTML=session.labels.map((l,i)=>`<div style="color:${judgmentColors[i]}"><span>${l}</span><b id="judge${i}">0</b></div>`).join('');$('liveRate').textContent=`${session.rate.toFixed(2)}× · ${settings.ruleset.toUpperCase()} WINDOWS`;$('liveOffset').textContent=`Offset ${opts.offset>=0?'+':''}${opts.offset} ms`;$('pausePlay').textContent='Ⅱ Pause';clock.start(opts.start,opts.rate,settings.leadIn,playing.settings);updatePractice();updateLive();$('game').focus();if(clock.error)toast(clock.error,7000);else if(!blob&&!chart.generated)toast('No audio attached — silent practice. Use Attach audio in the library.',6000)}catch(e){if(token!==runToken)return;clock.stop();playing=null;$('playScreen').hidden=true;$('app').hidden=false;document.querySelector('header').hidden=false;toast('Could not start: '+e.message,7000)}}
function updatePractice(){if(!playing)return;let p=playing;$('seek').disabled=!p.practice||p.mode==='replay';$('playMode').textContent=p.mode==='replay'?'REPLAY':p.mode==='auto'?'AUTOPLAY':p.practice?'PRACTICE':'FULL RUN';$('practiceInfo').innerHTML=p.practice?`A <b>${fmt(p.mode==='replay'?p.session.start:config.a)}</b> → B <b>${fmt(p.mode==='replay'?p.session.end:config.b)}</b><br>${p.loop?'LOOP ON':'SINGLE ATTEMPT'}<br>Target ${settings.target.toFixed(1)}%${settings.autoRate?'<br>AUTO RATE ON':''}`:'Complete chart<br>No seeking during full runs';$('toggleLoop').classList.toggle('accent',p.loop);$('toggleLoop').disabled=!p.practice||p.mode==='replay';$('markA').disabled=!p.practice||p.mode==='replay';$('markB').disabled=!p.practice||p.mode==='replay'}
function feedback(h){if(!h||!playing)return;renderer.hit(h);$('lastHit').textContent=playing.session.labels[h.grade]+(h.error===null?'':` ${h.error>=0?'+':''}${h.error.toFixed(1)}ms`);$('lastHit').style.color=judgmentColors[h.grade];if(h.kind==='head'&&h.grade<5&&playing.mode!=='replay')clock.hit(playing.settings.hitVolume)}
function updateLive(){if(!playing)return;let s=playing.session;$('liveScore').textContent=String(s.score).padStart(7,'0');$('liveAcc').textContent=s.accuracy.toFixed(2)+'%';$('liveCombo').textContent=s.combo+'×';$('life').style.width=s.health*100+'%';s.counts.forEach((n,i)=>$('judge'+i).textContent=n)}
function gameFrame(){let p=playing;if(p){let t=clock.time();if(!p.paused){let opportunity=p.settings.skipEnabled?skipOpportunity(p.session.notes,t,{start:p.session.start,end:p.session.end,rate:p.session.rate}):null;$('skipSong').hidden=!opportunity;$('skipSong').textContent=opportunity?'Skip '+opportunity.type+' ››  Tab':'';if(opportunity&&p.settings.autoSkipIntro&&opportunity.type==='intro'&&!p.replay){skipSong();t=clock.time()}if(p.replay){let skip=p.replay.skips?.[p.replaySkipCursor];if(skip&&t>=skip.from){clock.start(skip.to,p.session.rate,0,p.settings);p.replaySkipCursor++;t=clock.time()}while(p.replayCursor<p.replay.events.length&&p.replay.events[p.replayCursor].t<=t){let e=p.replay.events[p.replayCursor++];p.session.tick(e.t);let hit=e.down?p.session.press(e.lane,e.t):p.session.release(e.lane,e.t);if(Array.isArray(hit))hit.forEach(feedback);else feedback(hit)}}p.session.tick(t,p.mode==='auto').forEach(feedback);clock.metronome(p.chart,t,p.settings.metronome);if(p.session.hits.length!==p.lastHitCount){p.lastHitCount=p.session.hits.length;updateLive()}if(!p.settings.noFail&&p.session.health<=0&&p.mode!=='auto'&&p.mode!=='replay'){endAttempt(true);requestAnimationFrame(gameFrame);return}if(t>=p.session.end+(Math.max(0,p.session.offset)+p.session.missWindow*(p.session.lazer?1.5:1)+50)/1000*p.session.rate){if(p.loop)completeLoop();else endAttempt(false);requestAnimationFrame(gameFrame);return}}if(p.paused)$('skipSong').hidden=true;renderer.draw(t,p.paused?'paused':'playing');if(performance.now()-p.lastUI>70){p.lastUI=performance.now();$('timeNow').textContent=fmt(t);$('playTime').textContent=fmt(t)+' / '+fmt(p.session.end);if(!$('seek').matches(':active'))$('seek').value=clamp(t,0,p.chart.duration)}}requestAnimationFrame(gameFrame)}
function makeRecord(aborted=false){let p=playing,s=p.session;return{id:uid(),chartId:p.chart.id,title:p.chart.title,version:p.chart.version,keys:p.chart.keys,date:Date.now(),rate:s.rate,offset:s.offset,windows:[...s.windows],missWindow:s.missWindow,labels:s.labels,ruleset:p.settings.ruleset,start:s.start,end:s.end,mirror:!!p.opts.mirror,random:!!p.opts.random,noLN:!!p.opts.noLN,seed:p.opts.seed,practice:p.practice,aborted,score:s.score,accuracy:s.accuracy,maxCombo:s.maxCombo,counts:[...s.counts],hits:[...s.hits],events:[...s.events],skips:[...(p.skips||[])],total:s.total,elapsed:Math.max(0,clock.time()-s.start)/s.rate}}
